shell_commands:
cat << 'EOF' > test-ajv.ts
import Ajv from 'ajv';
const a = new Ajv();
EOF
npx tsc test-ajv.ts --noEmit

cat << 'EOF' > test-ajv.ts
import Ajv from 'ajv';
const a = new Ajv();
EOF
npx tsc --project tsconfig.json --noEmit test-ajv.ts

cat << 'EOF' > src/test-ajv.ts
import Ajv from 'ajv';
const a = new Ajv();
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
import type AjvClass from 'ajv';

const Ajv = AjvMod as unknown as typeof AjvClass;
const a = new Ajv();
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import { default as Ajv } from 'ajv';
const a = new (Ajv as any)();
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
import AjvCore from 'ajv/dist/core.js';
const ajv = new (AjvMod as unknown as typeof AjvCore)({});
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
const Ajv = AjvMod.default;
const ajv = new Ajv({});
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
const Ajv = (AjvMod.default || AjvMod) as typeof AjvMod.default;
const ajv = new Ajv({});
console.log(ajv);
EOF
npm run typecheck && node --experimental-vm-modules --input-type=module -e "import './dist/test-ajv.js'"

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
const AjvClass = (AjvMod as any).default || AjvMod;
const ajv = new AjvClass({ strict: false }) as InstanceType<typeof AjvMod>;
EOF
npm run typecheck

cat << 'EOF' > src/test-ajv.ts
import AjvMod from 'ajv';
const Ajv = ((AjvMod as any).default || AjvMod) as unknown as typeof AjvMod.default;
const ajv = new Ajv({ strict: false });
EOF
npm run typecheck

cat << 'EOF' > run-test.js
